using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;

namespace Testplan {
    // The browser supplies inputs, never device bytes generated by JavaScript.
    // All existing instrument/recipe methods execute on their original STA/UI thread.
    internal sealed class WorkspaceBackend : IDisposable {
        private readonly UART serial;
        private readonly CA410 meter;
        private readonly ARMCode arm;
        private readonly Control recipe;
        private readonly Pattern pattern;
        private readonly List<WebPoint> points=new List<WebPoint>();
        private bool disposed;
        internal bool Busy {get;private set;}
        internal static readonly HashSet<string> Operations=new HashSet<string>(StringComparer.Ordinal){"state","set","serial.connect","serial.scan","serial.send","serial.clear","meter.connect","meter.disconnect","meter.measure","arm.format","arm.comment","arm.download","arm.clear","sheet.export","sheet.clear","recipe.run","recipe.current","recipe.step","recipe.format","recipe.add","recipe.up","recipe.down","recipe.clear","recipe.import","recipe.export","recipe.browse","pattern.select","pattern.rgb","pattern.gray","pattern.back"};
        internal WorkspaceBackend(){
            AppLicense.Ensure();
            try{serial=new UART();meter=new CA410();arm=new ARMCode();recipe=new Control();pattern=new Pattern();
                serial.WebInitialize();recipe.WebInitialize();
                // These subscriptions replace the native Chart display, not the measurement producer.
                DataChart.fs.intevent+=ResetPoints;DataChart.fs.intstrstrevent+=AppendPoint;
            }catch{Dispose();throw;}
        }
        private void ResetPoints(int series){AppLicense.Ensure();points.Clear();}
        private void AppendPoint(int series,string x,string y){AppLicense.Ensure();double value;if(!double.TryParse(y,NumberStyles.Float,CultureInfo.CurrentCulture,out value)||double.IsNaN(value)||double.IsInfinity(value))throw new InvalidOperationException("原测量结果不是有效数值。");points.Add(new WebPoint{x=x,y=value});}
        internal WebState Snapshot(){
            AppLicense.Ensure();if(disposed)throw new ObjectDisposedException("WorkspaceBackend");
            var state=new WebState{authorized=true,busy=Busy,account=AppLicense.Account,edition=AppLicense.Edition,test=DataChart.CurrentTest};
            serial.WebRead(state);meter.WebRead(state);arm.WebRead(state);recipe.WebRead(state);pattern.WebRead(state);
            state.points.AddRange(points.Select(p=>new WebPoint{x=p.x,y=p.y}));
            state.metric=(state.test=="VCOM"||state.test=="Flicker")?(CA410.FMAcheck=="true"?"FMA":"JEITA"):"Lv";state.unit=state.metric=="FMA"?"%":state.metric=="JEITA"?"dB":"cd/m²";
            return state;
        }
        internal WebReply Execute(WebRequest request){
            AppLicense.Ensure();if(disposed)throw new ObjectDisposedException("WorkspaceBackend");
            var operation=request.operation;
            if(!Operations.Contains(operation))throw new InvalidOperationException("未允许的本机操作。");
            if(Busy&&operation!="state")throw new InvalidOperationException("配方或设备操作进行中，请先停止后再修改。");
            if(operation=="state")return new WebReply{id=request.id,ok=true,state=Snapshot()};
            var args=request.args??new WebArguments();
            serial.WebApply(args.fields);meter.WebApply(args.fields);arm.WebApply(args.fields);recipe.WebApply(args);pattern.WebApply(args.fields);
            bool execution=operation=="recipe.run"||operation=="recipe.current"||operation=="recipe.step";
            Busy=true;
            try {
                if(operation.StartsWith("serial.",StringComparison.Ordinal))serial.WebAction(operation);
                else if(operation.StartsWith("meter.",StringComparison.Ordinal))meter.WebAction(operation);
                else if(operation.StartsWith("arm.",StringComparison.Ordinal)||operation.StartsWith("sheet.",StringComparison.Ordinal))arm.WebAction(operation,args);
                else if(operation.StartsWith("recipe.",StringComparison.Ordinal))recipe.WebAction(operation,args);
                else if(operation.StartsWith("pattern.",StringComparison.Ordinal))pattern.WebAction(operation,args);
                else if(operation!="set")throw new InvalidOperationException("未允许的本机操作。");
                AppLicense.Ensure();
            } finally {if(execution)recipe.WebStop();Busy=false;}
            return new WebReply{id=request.id,ok=true,state=Snapshot(),recipeRuns=operation=="recipe.format"||operation=="recipe.import"?recipe.WebRichText():null};
        }
        // Stop/disconnect remain available even when the license is invalid.
        internal void Stop(){if(!disposed&&recipe!=null)recipe.WebStop();}
        internal void Disconnect(){Stop();if(UART.sp.IsOpen)UART.sp.Close();serial.RefreshDeviceState();if(meter!=null)meter.DisconnectFromWorkspace();}
        public void Dispose(){if(disposed)return;Stop();disposed=true;DataChart.fs.intevent-=ResetPoints;DataChart.fs.intstrstrevent-=AppendPoint;try{DisconnectHardware();}catch{}if(serial!=null){serial.WebDetach();serial.Dispose();}if(meter!=null)meter.Dispose();if(arm!=null){arm.WebDetach();arm.Dispose();}if(recipe!=null){recipe.WebDetach();recipe.Dispose();}if(pattern!=null)pattern.Dispose();}
        private void DisconnectHardware(){if(UART.sp.IsOpen)UART.sp.Close();if(meter!=null)meter.DisconnectFromWorkspace();}
    }
}
